@patch
def _floquet_products(self:LGSSystem, vg, n_vector, T): 
    return {
        # 'reconstruct': floquet_reconstruction_operator(n_vector, T),
        # 'total_population': velocity_sum(vg) * self.total_population, 
        # 'population_distribution': velocity_normalize(vg) * self.total_population, 
        'reconstructed_level_population': floquet_reconstruction_operator(n_vector, T) * vg.sum() * self.level_population, 
        # 'level_population_distribution': velocity_normalize(vg) * self.level_population, 
        # 'flux': self.flux,
        'flux_distribution': vg.normalize() * self.Flux,
        'reconstructed_flux': floquet_reconstruction_operator(n_vector, T) * self.Flux,
        'reconstructed_flux_distribution': floquet_reconstruction_operator(n_vector, T) * vg.normalize() * self.Flux,
        'reconstructed_total_flux': floquet_reconstruction_operator(n_vector, T) * (vg.sum() * self.Flux),
        # 'velocity_sum': velocity_sum(vg),
        # 'velocity_normalize': velocity_normalize(vg),
    }

